xhtml:iframe.style:
position:absolute;
inset:0;
width:100%;
height:100%;
border:0;
margin:0;
padding:0;
display:block;
overflow:auto;

svg.script:
(function () {

    const encoded = "PGh0bWw+PGJvZHk+PHdpZGdldGJvdCBzZXJ2ZXI9IjE1MjUyNDE4MTAwMDYzMTEwODMiIHdpZHRoPSI4MDAiIGhlaWdodD0iNjAwIj48L3dpZGdldGJvdD48c2NyaXB0IHNyYz0iaHR0cHM6Ly9jZG4uanNkZWxpdnIubmV0L25wbS9Ad2lkZ2V0Ym90L2h0bWwtZW1iZWQiPjwvc2NyaXB0PjwvYm9keT48L2h0bWw+";

    const binary = atob(encoded);

    const bytes = new Uint8Array(binary.length);

    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }

    const html = new TextDecoder("utf-8").decode(bytes);

    const frame = document.getElementById("html-frame");

    if (!frame) {
        return;
    }

    frame.srcdoc = html;

})();
